package net.flashlight.battery;
import net.minecraft.client.Minecraft;import net.minecraft.world.phys.Vec3;import net.minecraft.world.item.ItemStack;import net.minecraft.resources.ResourceLocation;
public class EntityChecks14{
 static int n;static void ok(boolean b,String m){if(!b)throw new AssertionError(m);n++;}
 public static class World extends ShadowChecks6.World{long time;public long getGameTime(){return time;}}
 public record Box(Vec3 getCenter){}
 public static class Actor extends ShadowChecks6.Actor{public Box getBoundingBox(){return new Box(new Vec3(x,1.5,z));}public float getBbWidth(){return .6f;}}
 static ItemStack item(String id){return new ItemStack(ResourceLocation.parse(id),1);}
 public static void main(String[]args){var mc=Minecraft.INSTANCE;World w=new World();Actor p=new Actor();p.world=w;p.main=item("minecraft:stick");p.inv.stacks[4]=item("flashlight:flashlight");Power.charge(p.inv.stacks[4],100);w.players.add(p);mc.player=p;mc.level=w;Light6.tick();int sky=7<<20;ok(EntityLight14.light(p,0,sky)==(sky|96),"hands use native block light from inventory flashlight");Actor near=new Actor();near.z=3;int lit=EntityLight14.light(near,0,sky);ok((lit&240)>0&&(lit&~240)==sky,"entity native skin brightness and sky coordinate");int before=w.queries;for(int i=0;i<40;i++)EntityLight14.light(near,0,sky);ok(w.queries==before,"reuse occlusion per tick");w.time+=4;EntityLight14.light(p,0,sky);EntityLight14.rays=EntityLight14.BUDGET;ok((EntityLight14.light(near,0,sky)&240)>0,"recent valid visibility survives exhausted ray budget without flicker");w.time+=11;EntityLight14.light(p,0,sky);EntityLight14.rays=EntityLight14.BUDGET;ok(EntityLight14.light(near,0,sky)==sky,"expired visibility is not reused through a possible new wall");EntityLight14.rays=0;Actor wall=new Actor();wall.z=7;ok(EntityLight14.light(wall,0,0)==0,"solid wall blocks entity illumination");Actor side=new Actor();side.x=10;side.z=3;ok(EntityLight14.light(side,0,0)==0,"outside cone unchanged");for(double power:new double[]{0,.01,.1,.5,1}){ok((EntityLight14.pack(sky,power)&~240)==sky,"sky bits unchanged");ok((EntityLight14.pack(sky|240,power)&240)==240,"never darken existing native light");}w.time++;before=w.queries;for(int i=0;i<300;i++){Actor other=new Actor();other.z=3;other.x=i*.001;EntityLight14.light(other,0,0);}ok(w.queries-before<=EntityLight14.BUDGET,"bounded entity collision work");ok(EntityLight14.CACHE.size()<=EntityLight14.MAX,"bounded entity cache");p.inv.stacks[4]=item("flashlight:flashlight_off");Light6.tick();ok(EntityLight14.light(near,0,sky)==sky&&EntityLight14.light(p,0,sky)==sky,"off restores original native input");mc.level=null;ok(EntityLight14.light(near,0,sky)==sky,"unloaded level safe");System.out.println("ENTITY_HAND_NATIVE_LIGHT_CONE_WALL_INVENTORY_OFF_SKY_CACHE_BUDGET_CHECKS="+n);}
}
